// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, CATEGORIES, HITS } from './script'

const RADAR = 196
const ORBIT = 78
const color = (category: string) =>
  CATEGORIES.find((item) => item.key === category)?.color ?? '#c9c9d3'
const SLOTS = HITS.map((_, index) => {
  const angle = (index / HITS.length) * Math.PI * 2 - Math.PI / 2
  return {
    x: Math.round(RADAR / 2 + Math.cos(angle) * ORBIT),
    y: Math.round(RADAR / 2 + Math.sin(angle) * ORBIT),
  }
})
const BLIPS = HITS.map((_, index) => {
  const angle = (index / HITS.length) * Math.PI * 2 + 0.6
  const radius = 30 + ((index * 23) % 50)
  return {
    x: Math.round(RADAR / 2 + Math.cos(angle) * radius),
    y: Math.round(RADAR / 2 + Math.sin(angle) * radius),
  }
})
const ORDERED = CATEGORIES.flatMap((category) =>
  HITS.filter((hit) => hit.category === category.key),
)

const build: Build = ({ tl, q, qa, step, final, type, wait }) => {
  tl.set([...qa('badge-inner'), ...qa('blip')], { xPercent: -50, yPercent: -50 }, 0)

  step(0)
  tl.fromTo(
    q('radar'),
    { opacity: 0, scale: 0.85 },
    { opacity: 1, scale: 1, duration: 0.5, ease: 'power3.out' },
    0.2,
  )
  tl.fromTo(q('sweep'), { rotation: 0 }, { rotation: 720, duration: 2.6, ease: 'none' }, '<')
  type('status', 'Scanning scripts, meta and globals…', { at: '<0.2', speed: 0.02 })

  step(1, '-=1')
  HITS.forEach((_, index) => {
    tl.fromTo(
      q(`blip-${index}`),
      { opacity: 0, scale: 0 },
      { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
      index === 0 ? 'step-1' : '<0.14',
    )
  })
  tl.fromTo(q('sweep'), { rotation: 0 }, { rotation: 360, duration: 1.4, ease: 'none' }, 'step-1')
  HITS.forEach((_, index) => {
    tl.fromTo(
      q(`badge-${index}`),
      {
        x: BLIPS[index].x - SLOTS[index].x,
        y: BLIPS[index].y - SLOTS[index].y,
        opacity: 0,
        scale: 0.4,
      },
      { x: 0, y: 0, opacity: 1, scale: 1, duration: 0.5, ease: 'power3.out' },
      index === 0 ? '+=0.1' : '<0.08',
    )
    tl.to(q(`blip-${index}`), { opacity: 0, duration: 0.2 }, '<')
  })
  tl.to(q('sweep'), { opacity: 0.25, duration: 0.4 }, '<')
  type('status', `${HITS.length} technologies detected`, { at: '<', speed: 0.02 })

  step(2, '+=0.3')
  tl.fromTo(
    qa('cat'),
    { opacity: 0, x: 10 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.1, ease: 'power3.out' },
  )
  tl.fromTo(
    qa('hit'),
    { opacity: 0, x: 10 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.08, ease: 'power3.out' },
    '<0.1',
  )
  tl.to(q('orbit'), { rotation: 30, duration: 1.6, ease: 'power1.inOut' }, '<')
  tl.to(qa('badge-inner'), { rotation: -30, duration: 1.6, ease: 'power1.inOut' }, '<')

  step(3, '+=0.2')
  ORDERED.forEach((hit, index) => {
    tl.fromTo(
      q(`evidence-${index}`),
      { opacity: 0 },
      { opacity: 1, duration: 0.2 },
      index === 0 ? undefined : '<0.12',
    )
    type(`evidence-${index}`, hit.evidence.replace(/^https?:\/\//, ''), { at: '<', speed: 0.008 })
  })
  final('+=0.2')
  wait(1.6)
}

export default function Demo() {
  return (
    <DemoStage
      label="Tech Stack scanning a storefront and listing the frameworks, CMS, analytics and CDN it found, with evidence"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full gap-3">
          <div className="flex w-[196px] shrink-0 flex-col items-center gap-2">
            <div
              data-d="radar"
              className="relative rounded-full border border-[var(--accent)]/30 opacity-0"
              style={{ width: RADAR, height: RADAR }}
            >
              {[0.66, 0.33].map((ratio) => (
                <span
                  key={ratio}
                  className="absolute rounded-full border border-[var(--accent)]/20"
                  style={{ inset: Math.round((RADAR * (1 - ratio)) / 2) }}
                />
              ))}
              <span className="absolute inset-x-0 top-1/2 h-px bg-[var(--accent)]/15" />
              <span className="absolute inset-y-0 left-1/2 w-px bg-[var(--accent)]/15" />
              <span
                data-d="sweep"
                className="absolute inset-0 rounded-full"
                style={{
                  background:
                    'conic-gradient(from 0deg, rgba(125,211,252,0.45), rgba(125,211,252,0) 70deg, rgba(125,211,252,0) 360deg)',
                }}
              />
              {BLIPS.map((blip, index) => (
                <span
                  key={index}
                  data-d={`blip blip-${index}`}
                  className="absolute size-2 rounded-full opacity-0"
                  style={{
                    left: blip.x,
                    top: blip.y,
                    backgroundColor: color(HITS[index].category),
                    boxShadow: `0 0 10px ${color(HITS[index].category)}`,
                  }}
                />
              ))}
              <div data-d="orbit" className="absolute inset-0">
                {HITS.map((hit, index) => (
                  <span
                    key={hit.name}
                    data-d={`badge-${index}`}
                    className="absolute opacity-0"
                    style={{ left: SLOTS[index].x, top: SLOTS[index].y }}
                  >
                    <span
                      data-d="badge-inner"
                      className="absolute left-0 top-0 block whitespace-nowrap rounded-full border bg-canvas px-1.5 py-0.5 text-[8.5px] font-medium"
                      style={{ color: color(hit.category), borderColor: color(hit.category) }}
                    >
                      {hit.name.replace(' / GTM', '')}
                    </span>
                  </span>
                ))}
              </div>
            </div>
            <p data-d="status" className="h-3 text-center text-[9.5px] text-muted" />
          </div>
          <div className="min-w-0 flex-1 space-y-1">
            {CATEGORIES.map((category) => {
              const hits = HITS.filter((hit) => hit.category === category.key)
              if (!hits.length) return null
              return (
                <div key={category.key} data-d="cat" className="opacity-0">
                  <p
                    className="text-[8.5px] font-medium uppercase tracking-wider"
                    style={{ color: category.color }}
                  >
                    {category.label}
                  </p>
                  {hits.map((hit) => {
                    const order = ORDERED.indexOf(hit)
                    return (
                      <div
                        key={hit.name}
                        data-d="hit"
                        className="mt-0.5 rounded-md border border-line bg-ink/[0.03] px-2 py-0.5 opacity-0"
                      >
                        <p className="text-[10px] font-medium text-ink">{hit.name}</p>
                        <p
                          data-d={`evidence-${order}`}
                          className="h-3 truncate font-mono text-[8px] text-muted opacity-0"
                        />
                      </div>
                    )
                  })}
                </div>
              )
            })}
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
